W=Path(__file__).resolve().parent;D=W/'sources/review-p152-p164'
IDS='p152 p153 p154 p155 p156 p157 p158 p159 p160 p161-163 p164'.split()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
