def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
notes={
'p152':'Gesamten Satz und Erwerbsalternativen Anmeldung/Eintragung/Benutzung/notorische Bekanntheit sowie geschäftliche Bezeichnungen gelesen. Vorbehalt der nachfolgenden Regeln und grundsätzliche Anwendung des neuen Gesetzes zutreffend. Fiktive alte Produktmarke verlangt Erwerbs-/Kontinuitätsnachweise; keine allgemeine Unangreifbarkeit oder erfundene historische Voraussetzungen. Nach Prüfung beibehalten.',
'p153':'Beide Absätze mit §21 vollständig geprüft. Präzisiert: fehlender Anspruch gerade des Inhabers gegen konkrete Nutzung statt allgemeiner Rechtmäßigkeit; bloße Anmeldung aus §152 nicht als zusätzliche Abs.1-Alternative. Fortsetzung und tatsächlicher Umfang eigenständig zu belegen. Fristbeginn 1.1.1995 hebt Kenntnis, Duldung und Bösgläubigkeitsausnahme nicht auf. Fiktives regionales Geschäftszeichen mit konkreter Beweiskette; ungeeigneter BGH-PDF-Suchtreffer nicht zitiert.',
'p154':'Beide Absätze samt §29Abs.2/3 gelesen. Altes dingliches Recht, Vollstreckungsmaßnahme und Konkursverfahren von neuem Erwerb oder heutiger Insolvenzeinordnung getrennt. Nachweis und Registerpublizität vermitteln weder Heilung noch automatisch besseren Rang. Sachbezogenes Sicherungs-/Verwertungsbeispiel angemessen; nach Prüfung erhalten.',
'p155':'Gesamten Satz und §30 gelesen. Fehlende ausdrückliche Erwähnung des Anmelderechts ergänzt. Nur Wirkung Abs.5 zeitlich begrenzt, nicht gesamte Übernahme des §30; Bestandswirkung gegenüber späterem Übergang/weiterer Lizenz, keine Vertragsheilung oder Gebietserweiterung. Konkrete 1993/1994/2004-Verfügungskette differenziert; historische Konkurrenzlage nicht aus Erinnerung ergänzt.',
'p156':'Beide Sätze, §50Abs.1–3 und heutige §§53/54 gelesen. Vor1995-Amtsverfahren/Antrag nach damaligem §10Abs.2Nr.2WZG und spätere Verfahren gegen Vor1995-Eintragung konkret getrennt. Kumulative Schutzunfähigkeit und Abgrenzung relativer Gründe zu §157 erklärt. Überholter §54-Verweis ausdrücklich historisch eingeordnet; heutiger Antrag §53/50 und ex officio §50Abs.3, kein Beitritt als allgemeine Einleitungsgrundlage. Historische WZG-Details nicht erfunden.',
'p157':'Alle Sätze beider Absätze mit §§51/53/55/158Abs.6 gelesen. Zeitliche Verfahrensgruppen und Datum 1.5.2020 konkretisiert. Doppelprüfung in systematischem Bezug auf ältere Rechte, nicht jeder Verfallsfall. Abs.2 nur §51Abs.2S.1/2, kein Ausschluss des heutigen Zustimmungs-S.3; Kenntnis/Duldung/Bösgläubigkeit nicht aufgehoben. Eigenständige systematische Erläuterung, keiner ungeprüften Gerichtsentscheidung zugeschrieben.',
'p158':'Alle elf Absätze und sämtliche Verweise gelesen. EGBGB-Verjährungsüberleitung vollständig als gezielten Fremdtext geprüft. Anmelde-/Widerspruchs-/Antrags-/Klage-/Rechtsbehelfs-/Eintragungsstichtage getrennt; nur jeweils verwiesene Normen historisch eingefroren. §§42(3)/(4),26/43,49/51/55,8Nr.9–12,50Abs.2,64/66,102Abs.4 und127Abs.6 geprüft. Art.5Nr.36/Art.16 BGBl2026INr9 bestätigen neue Abs.11-Unterrichtung; keine endgültige EU-Registrierung fingiert. Zwei amtliche BPatG-Volltexte vollständig gelesen; genaue begrenzte Aussagen und offene Fragen, alter wandernder Zeitraum nicht zu heutigem §43 verallgemeinert. Fiktive 2018/2019-Akten machen verschiedene Stichtage greifbar.',
'p159':'Beide Absätze mit aktuellem §47 gelesen. Maßgebliche alte Eintragung vor14.1.2019 und Fortgeltung gerade §47Abs.1 für Schutzdauerende richtig; keine pauschale Altanmeldeanknüpfung. Kostenrechtliche Gruppe und zwölfmonatiger Bezug ab31.1.2019 richtig. Konkrete alte §§3/5/7PatKostG ergeben sich aus unverändertem abgedrucktem Wortlaut; historische Gebührenbeträge/Formeln werden ausdrücklich nicht ungesichert ergänzt. Keine zusätzliche allgemeine Nachfrist erfunden. Nach Prüfung erhalten.',
'p160':'Beide Absätze samt Nr.1/2 und frisch amtlichen §2StGB/§4OWiG vollständig gelesen. Tatbestandsgenauer Katalog §144/145Abs.2–4, besondere Aufhebung/Nichtanwendung und Tatzeitregel entfaltet; §143/145Abs.1 nicht hineingelesen. Mildestes-Gesetz-Ausnahme keine nachträgliche neue Strafbarkeit. Erforderliche Verweisanpassung bei Änderung versus inhaltsgleicher Ersetzung, BMJ ohne Bundesrat; früherer Delegationssatz 2026 ausdrücklich gestrichen. Fiktiver2027-Vorgang klar als nicht beschlossene Reform gekennzeichnet.',
'p161-163':'Amtliches einziges Sammelrecord enbez (XXXX) §§161bis163, leeres operatives Content und Metadaten-Titel (weggefallen) unmittelbar kontrolliert. Erläuterungen aller drei leeren Nummern erhalten, keine frei erfundenen heutigen Tatbestände; historische Verweise nur nach eigenständiger Fassungsprüfung. Keine Aufteilung in drei scheinbar separate amtliche Datensätze. Technischer Kurztext nach Prüfung beibehalten.',
'p164':'Amtliche Metadaten (weggefallen) und tatsächlicher Content-Marker - geprüft. Kein materieller Tatbestand daraus erfunden. Praktische Übergangscheckliste trennt Rechtserwerb, Verfahren, Fassungen, Doppelprüfung und leere Nummern. Nach Prüfung beibehalten.'}
assert list(notes)==IDS
before=json.loads((D/'before-commentary.json').read_text());prior=json.loads((D/'prior-review-result.json').read_text())
current={m[1]:m[2].strip() for p in (W/'commentary').glob('*.md') for m in re.finditer(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',p.read_text(),re.M|re.S)}
assert len(current)==191 and set(before)==set(current)
changed=[i for i in IDS if before[i]!=current[i]];assert changed==['p153','p155','p156','p157','p158','p160']
assert all(before[i]==current[i] for i in before if i not in IDS)
units={u['id']:u for u in map(json.loads,(W/'units.jsonl').read_text().splitlines())};root=E.parse(D/'markeng.xml').getroot();compact=lambda s:re.sub(r'\s+','',s)
findings=[]
for i in IDS:
 u=units[i];n=next(n for n in root.findall('norm') if n.findtext('metadaten/enbez')==u['label']);c=n.find('textdaten/text/Content');s=''.join(c.itertext()) if c is not None else ''
 if i=='p161-163':assert not s.strip();s=n.findtext('metadaten/titel')
 assert compact(u['text'])==compact(s)
 findings.append(dict(id=i,label=u['label'],disposition='corrected' if i in changed else 'retained',finding=notes[i],paragraphs_and_lists_read=True,meaning_examples_crossrefs_authorities_repetition_checked=True,statutory_wording_agreement=True,official_doknr=n.attrib['doknr'],statutory_sha256=hashtext(u['text']),commentary_before_sha256=hashtext(before[i]),commentary_after_sha256=hashtext(current[i])))
casechecks=json.loads((D/'case-comparison.json').read_text());assert sum(x['official_nonempty_paragraphs_compared'] for x in casechecks)==80
cumulative=list(dict.fromkeys(prior['cumulative_reviewed_ids']+IDS));assert len(cumulative)==191 and set(cumulative)==set(units)
coverage=json.loads((W/'completeness-independent.json').read_text());q=json.loads((W/'quality-report.json').read_text());assert coverage['ok']
validated='--validated' in sys.argv;technical=json.loads((W/'validation.json').read_text()) if validated else None
if validated:assert technical['ok'] and technical['verbatim_ratio']==1.0 and not q['broken_local_links'] and not q['repeated_long_sentences'] and not q['placeholder_matches']
now=datetime.now(timezone.utc).isoformat()
limits=['Exactly the assigned eleven official units reviewed; 180 unassigned commentary blocks unchanged. Earlier review records retained, not independently rereviewed here. No whole-book completion, final assembly or external professional approval claimed.','Case research selective: two new BPatG decisions fully read and freshly official-verified for §158. Seventeen prior case cards retained unchanged without substantive rereview; no exhaustive later-case audit.','Current transition directions and targeted individual external references checked; no full reconstruction of every historical WZG, MarkenG, PatKostG, EU or implementing provision. Commentary explicitly requires historical texts for a concrete historical double test and does not fill statutory gaps from memory.','Firecrawl lacked credits; direct validated official HTTP captures used. A purported BGH PDF returned HTML and was rejected; its Content-Type/final URL were not recorded in first handler and are not reconstructed.','Current official consolidation and both relevant 2026 amendment/commencement sources checked; later-amendment search selective, not exhaustive BGBl pipeline audit.']
result=dict(complete=validated,task='bounded_independent_second_pass',units_reviewed=11,reviewed_ids=IDS,decisive_date='2026-10-19',reviewed_at=now,unresolved_blockers=[],findings=findings,limitations=limits,changed_ids=changed,retained_ids=[i for i in IDS if i not in changed],whole_book_complete=False,work_baseline_commit=(D/'baseline-commit.txt').read_text().strip(),baseline_evidence='sources/review-p152-p164/before-commentary.json',baseline_evidence_sha256=sha(D/'before-commentary.json'),unchanged_unassigned_units=180,unassigned_commentary_unchanged=True,prior_review_result='sources/review-p152-p164/prior-review-result.json',cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=191,cumulative_basis='180 from prior review record plus eleven actually reviewed in this process; administrative aggregation, no fresh whole-book review.',remaining_second_pass_units=0,final_whole_book_assembly_performed=False,case_checks=casechecks,source_preflight='preflight-result.json',source_verification='sources/verification.json',technical_validation=technical,technical_validation_pending=not validated,completeness=dict(expected=191,parsed=191,missing=coverage['missing'],extra=coverage['unexpected'],xml_character_mismatch=coverage['xml_character_mismatch']),quality=dict(broken_links=q['broken_local_links'],repeated_long_sentences=q['repeated_long_sentences'],placeholder_matches=q['placeholder_matches']))
save(W/'review-result.json',result)
status=json.loads((W/'status.json').read_text());status.update(stage='bounded_second_pass_complete' if validated else 'bounded_second_pass_validation_pending',task_scope='Exactly p152–p160, p161-163 and p164; eleven official units; no whole-book completion.',reviewed_ids=IDS,units_reviewed=11,review_result='review-result.json',review_completed_at=now if validated else None,whole_book_review_complete=False,independent_second_pass='Current eleven reviewed; inherited records account for other 180; no new whole-book review or final assembly.',updated_at=now,remaining_limitations=limits,unresolved_blockers=[],cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=191,remaining_second_pass_units=0,commentary_characters=sum(map(len,current.values())))
status['source_checks']['latest_verification']=max(f['accessed_at'] for f in json.loads((D/'fetches.json').read_text()))
for c in casechecks:
 if c['docket'] not in {x['docket'] for x in status['case_law_sources']}:status['case_law_sources'].append(dict(court=c['court'],date=c['date'],docket=c['docket'],card='cases/bpatg-'+c['slug']+'-uebergang.md',read_full_text=True))
status['case_law_provenance']='Two new BPatG decisions read fully and freshly official-verified in this batch; all 17 prior cards unchanged without substantive rereview.'
status['quality_checks'].update(output_local_links=q['checked_output_links'],broken_links=q['broken_local_links'],repeated_paragraphs=q['exact_repeated_paragraphs'],repeated_long_sentences=q['repeated_long_sentences'],other_commentary_blocks='All 180 unassigned blocks unchanged against baseline '+result['work_baseline_commit'],unchanged_commentary_units=185,retained_reviewed_units=5,corrected_reviewed_units=6)
if validated:status['validation_result']=technical
save(W/'status.json',status)
verification=json.loads((W/'sources/verification.json').read_text());fetches=json.loads((D/'fetches.json').read_text())
for f in fetches:
 assert sha(W/f['path'])==f['sha256'] and f['http_status']==200
 if f['path'] not in {x['path'] for x in verification['fetches']}:verification['fetches'].append(f)
verification['last_verified_at']=max(f['accessed_at'] for f in fetches);verification['bounded_review_p152_p164'].update(verified_at=verification['last_verified_at'],case_comparison='sources/review-p152-p164/case-comparison.json',case_full_text_read=True,external_references=['Art.229 §6 EGBGB','StGB §2','OWiG §4'],rejected_responses='sources/review-p152-p164/rejected-fetches.json')
save(W/'sources/verification.json',verification)
pf=json.loads((W/'preflight-result.json').read_text());pf['bounded_review_p152_p164_recheck'].update(verified_at=verification['last_verified_at'],assigned_version_analysis='sources/review-p152-p164/assigned-version-review.json',supplementary_source_limitations=limits[2:],reviewed_ids=IDS)
pf['limitations']=[s for s in pf['limitations'] if s!='Independent second pass remains pending.']
pf['limitations'].append('This process completes only the eleven-unit bounded second pass; earlier review records preserved, no whole-book completion claimed.') if not any('eleven-unit bounded' in s for s in pf['limitations']) else None
if validated:pf['bounded_review_p152_p164_recheck']['technical_validation']=technical
save(W/'preflight-result.json',pf)
print(json.dumps(dict(complete=validated,units_reviewed=11,corrected=6,retained=5,unassigned_unchanged=180,new_case_paragraphs=80)))
